#!/usr/bin/env node
// Invariant checks for prioritization-board-grid.html, the board (the one build since v1.88).
//
// The board used to be generated by build_prio_board.py and guarded by a test suite; both were
// lost with the machine they lived on, and the generator was retired on 11 Sep 2026. The HTML in
// git is the source, so the handful of invariants that suite held have to live somewhere. This is
// that somewhere.
//
//   node tools/check.mjs [path-to-html]
//   node tools/check.mjs --selftest        the award-order rule's own test, alone (it also runs in every check)
//
// Exits non-zero on the first failing check so it can gate a commit.

import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

// THE AWARD-ORDER RULE'S OWN TEST, ALONE (v1.95, item 56). The functions are declared further down, with the rule.
if (process.argv[2] === '--selftest') {
  const st = awardOrderSelftest();
  st.bad.forEach(b => console.log(`  FAIL  ${b}`));
  console.log(st.bad.length ? `\nthe award-order rule fails its own test: ${st.bad.length} case(s)\n`
    : `\nthe award-order rule's own test passed: ${st.refused} unsafe forms refused (the review's three bypasses among them), ${st.passed} valid forms passed\n`);
  process.exit(st.bad.length ? 1 : 0);
}

const FILE = process.argv[2] || new URL('../prioritization-board-grid.html', import.meta.url).pathname;
const src = readFileSync(FILE, 'utf8');
const lines = src.split('\n');

let failed = 0;
const pass = (m) => console.log(`  ok    ${m}`);
const fail = (m) => { console.log(`  FAIL  ${m}`); failed++; };

// Read an object/array literal declared as `const NAME = <literal>;` on one line. The board keeps
// every one of these on a single line, which is what makes this safe to do with a regex.
function literal(name, endsWith = ';') {
  const re = new RegExp(`^const ${name}\\s*=\\s*([\\s\\S]*?)${endsWith.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*$`, 'm');
  const m = src.match(re);
  if (!m) throw new Error(`could not find declaration of ${name}`);
  return new Function(`return (${m[1]})`)();
}

console.log(`\nchecking ${FILE}`);
console.log(`${lines.length} lines, ${(src.length / 1048576).toFixed(2)} MB\n`);

// ---- 1. the script actually parses -------------------------------------------------------------
// A board that will not open is the worst outcome this file has, and it is a silent one: the
// browser logs a SyntaxError to a console nobody has open and renders a blank page.
console.log('syntax');
{
  const start = lines.findIndex(l => l.startsWith('const SRC0 ='));
  const end = lines.length - lines.slice().reverse().findIndex(l => l.trim() === '</script>') - 1;
  if (start < 0 || end <= start) fail('could not locate the main script block');
  else {
    const js = lines.slice(start, end).join('\n');
    const tmp = join(mkdtempSync(join(tmpdir(), 'spmt-')), 'main.js');
    writeFileSync(tmp, js);
    try {
      execFileSync(process.execPath, ['--check', tmp], { stdio: 'pipe' });
      pass(`main script parses (${end - start} lines)`);
    } catch (e) {
      fail(`main script has a syntax error:\n${e.stderr?.toString() || e.message}`);
    }
  }
}

// ---- 2. the appropriation tables agree ---------------------------------------------------------
// The file's own comment at APPN_SLUGS explains the trap: these lists were duplicated in nine
// places, and a slug added to one but missed in another does not throw. It quietly covers one
// appropriation fewer -- a chip row missing a button, an export summing three of four -- and
// every figure it still prints reconciles, so nothing looks wrong.
console.log('\nappropriations');
try {
  const slugs = literal('APPN_SLUGS');
  const bySlug = {
    APPN_LBL: literal('APPN_LBL'),
    APPN_NAME: literal('APPN_NAME'),
    _SLUGMAP: literal('_SLUGMAP'),
    SRC_TABS: literal('SRC_TABS'),
  };
  const byLabel = {
    APPNS: literal('APPNS'),
    // `const _AP={...}[APPN];` — take the literal, not the lookup.
    _AP: literal('_AP', '[APPN];'),
  };

  pass(`APPN_SLUGS = [${slugs.join(', ')}]`);

  for (const [name, table] of Object.entries(bySlug)) {
    const keys = Object.keys(table);
    const missing = slugs.filter(s => !keys.includes(s));
    const extra = keys.filter(k => !slugs.includes(k));
    if (missing.length) fail(`${name} is missing: ${missing.join(', ')}`);
    else if (extra.length) fail(`${name} has slugs not in APPN_SLUGS: ${extra.join(', ')}`);
    else pass(`${name} covers all ${slugs.length}`);
  }

  // APPNS and _AP are keyed by the SHOUTING label, not the slug, so they join through APPN_LBL.
  const labels = slugs.map(s => bySlug.APPN_LBL[s]);
  for (const [name, table] of Object.entries(byLabel)) {
    if (!table) { fail(`${name} could not be read`); continue; }
    const keys = Object.keys(table);
    const missing = labels.filter(l => !keys.includes(l));
    const extra = keys.filter(k => !labels.includes(k));
    if (missing.length) fail(`${name} is missing: ${missing.join(', ')}`);
    else if (extra.length) fail(`${name} has labels not in APPN_LBL: ${extra.join(', ')}`);
    else pass(`${name} covers all ${slugs.length} (keyed by label)`);
  }

  // _AP rows carry the slug back; a row whose slug disagrees with its label routes saves to the
  // wrong localStorage key, which looks like data loss rather than a mapping bug.
  if (byLabel._AP) {
    const wrong = slugs.filter(s => byLabel._AP[bySlug.APPN_LBL[s]]?.slug !== s);
    if (wrong.length) fail(`_AP rows whose slug disagrees with their label: ${wrong.join(', ')}`);
    else pass('_AP slugs round-trip to their labels');
  }
} catch (e) {
  fail(e.message);
}

// ---- 3. the save path can still find its target ------------------------------------------------
// buildSavedHtml() rewrites the pubState tag with a regex. If that tag is edited into a shape the
// regex no longer matches, Save silently writes a file with the OLD state in it.
console.log('\nsave path');
{
  const TAG = /<script type="application\/json" id="pubState">([\s\S]*?)<\/script>/;
  const hits = src.split('<script type="application/json" id="pubState">').length - 1;
  if (hits !== 1) fail(`expected exactly 1 literal pubState tag, found ${hits}`);
  else pass('exactly one literal pubState tag');

  const m = src.match(TAG);
  if (!m) fail('buildSavedHtml’s regex does not match the pubState tag');
  else pass('buildSavedHtml’s regex matches it');

  if (!/const SRC0 = '<!DOCTYPE html>\\n' \+ document\.documentElement\.outerHTML;/.test(src))
    fail('SRC0 is not captured as outerHTML at boot — saves would write the wrong source');
  else pass('SRC0 captured at boot');
}

// ---- 4. no data in the committed copy ----------------------------------------------------------
// The repo holds the PROGRAM. A saved working board is program + data fused together, and that
// data is budget detail that does not belong on GitHub.
console.log('\nno data committed');
{
  const m = src.match(/<script type="application\/json" id="pubState">([\s\S]*?)<\/script>/);
  const body = (m?.[1] || '').trim();
  if (body !== 'null' && body !== '') fail(`pubState carries ${body.length} bytes of state — do not commit a populated board`);
  else pass('pubState is null');

  try {
    const appns = literal('APPNS');
    const withData = Object.entries(appns).filter(([, v]) => v.items?.length || v.services?.length);
    if (withData.length) fail(`APPNS carries data for: ${withData.map(([k]) => k).join(', ')}`);
    else pass('APPNS is empty');
  } catch (e) { fail(e.message); }
}

// ---- 5. still offline -------------------------------------------------------------------------
// This runs from a share or a file:// URL on machines with no route to a CDN. A dependency added
// here does not degrade, it just fails to load.
console.log('\noffline');
{
  const short = lines.filter(l => l.length < 2000).join('\n');
  const urls = [...short.matchAll(/https?:\/\/[A-Za-z0-9.\-]+/g)].map(m => m[0]);
  const external = [...new Set(urls)].filter(u => !/schemas\.openxmlformats\.org|www\.w3\.org/.test(u));
  if (external.length) fail(`external references: ${external.join(', ')}`);
  else pass(`no external hosts (${new Set(urls).size} namespace URIs only)`);

  // one tag at a time: `[^>]+` alone ran from a "<script" inside the board's own code to a "src=" 9,000
  // characters later (v1.85 flagged itself). An attribute list is never that long.
  if (/<script\b[^>]{0,400}\ssrc\s*=|<link\b[^>]{0,400}\shref\s*=\s*["']?https?:/i.test(short)) fail('an external script or stylesheet is linked');
  else pass('no linked scripts or stylesheets');
}

// ---- 5b. the Content-Security-Policy (v2.04, item 106): the browser refuses any connection to another host ---------------
// The file makes no request to another host since items 110-111; the policy makes sure one added by mistake cannot. It must
// be in the head, before any script, and no directive may name a host or a network scheme.
console.log('\ncontent security policy');
{
  const m = src.match(/<meta http-equiv="Content-Security-Policy" content="([^"]*)">/);
  if (!m) fail('the Content-Security-Policy meta tag is missing');
  else {
    const pol = m[1], at = src.indexOf(m[0]), firstScript = src.search(/<script\b/i);
    const dir = Object.fromEntries(pol.split(';').map(s => s.trim()).filter(Boolean).map(s => { const p = s.split(/\s+/); return [p[0], p.slice(1)]; }));
    if (firstScript >= 0 && at > firstScript) fail('the policy comes after a script, so that script runs unchecked');
    else pass('the policy is set before any script runs');
    const net = pol.split(/[;\s]+/).filter(x => /^(https?:|wss?:|\*|[a-z0-9.-]+\.[a-z]{2,})/i.test(x));
    if (net.length) fail(`the policy allows a network source: ${net.join(', ')}`);
    else pass('no directive allows a host or a network scheme');
    for (const d of ['default-src', 'connect-src', 'object-src', 'base-uri', 'form-action'])
      if (!dir[d]) fail(`the policy has no ${d}`);
    if (dir['connect-src'] && dir['connect-src'].join(' ') !== "'self' file: data: blob:") fail(`connect-src is "${dir['connect-src'].join(' ')}"`);
    else pass("connect-src is 'self' file: data: blob:");
  }
}

// ---- every inline handler names a function that exists --------------------------------------
// A control whose handler was renamed does not throw at load and does not look broken: the markup
// is there, the checkbox draws, the click raises a ReferenceError into the console and NOTHING
// HAPPENS. `pmoPick` shipped that way -- it became `subPick` in a collision rename and this one
// call site was missed, so every per-row tick in the submittal review was dead while "Tick all"
// still worked. The reviewer would have accepted all or nothing without ever being told.
// Static, so it covers panels no audit happens to open.
{
  console.log('\ninline handlers');
  const names = new Set();
  const HRE = /on(?:click|change|input|submit|keydown|keyup|blur|focus|dblclick|mousedown|contextmenu)\s*=\s*(?:"|\\"|&quot;|')\s*([A-Za-z_$][\w$]*)\s*\(/g;
  for (const m of src.matchAll(HRE)) names.add(m[1]);
  const defined = new Set();
  const DRE = /(?:^|\n)\s*(?:async\s+)?function\s+([A-Za-z_$][\w$]*)|(?:^|\n)\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=/g;
  for (const d of src.matchAll(DRE)) defined.add(d[1] || d[2]);
  // `onclick="if(...)"` and friends are inline statements, not a call to a named function.
  const KEYWORD = new Set(['if', 'for', 'while', 'switch', 'return', 'typeof', 'void', 'delete', 'do', 'try']);
  const GLOBAL  = new Set(['alert', 'confirm', 'prompt', 'print', 'open', 'close', 'event']);
  const missing = [...names].filter(n => !defined.has(n) && !KEYWORD.has(n) && !GLOBAL.has(n)).sort();
  if (missing.length) fail(`inline handler names nothing: ${missing.join(', ')}`);
  else pass(`all ${names.size} inline handler names resolve`);
}

// ---- a value reaches handler code only through jsa() (v1.88) -----------------------------------
// Ids, keys, and service and office names arrive in files from other people. Written into an inline
// handler by hand -- onclick="f('+id+')" -- a quote in one ends the string and the rest of it is code
// that runs inside the board. v1.88 routed every such value through jsa(), which makes it a JSON string
// and escapes that for the attribute; this fails on a value concatenated into handler code any other way:
// straight after an opening quote the handler wrote (\' or &quot;), straight before its closing one,
// or into a template literal's quotes. A literal continuing a literal ("…,'\n +'&quot;m&quot;") is not a
// value, so a closing quote preceded by the end of another literal is let through.
{
  console.log('\nhandler values');
  const bad = [];
  const at = i => src.slice(0, i).split('\n').length;
  const comment = i => /^\s*(\/\/|\*|\/\*)/.test(lines[at(i) - 1] || '');
  const prevChar = i => { let j = i - 1; while (j >= 0 && /\s/.test(src[j])) j--; return src[j]; };
  for (const m of src.matchAll(/(\\'|&quot;)'\s*\+/g)) if (!comment(m.index)) bad.push([at(m.index), 'a value written straight after a quote the handler opened']);
  for (const m of src.matchAll(/\+\s*'(\\'|&quot;)/g))
    if (!comment(m.index) && !/['"`]/.test(prevChar(m.index))) bad.push([at(m.index), 'a value written straight before a quote the handler closes']);
  for (const m of src.matchAll(/\('"\s*\+/g))
    if (!comment(m.index) && !/_api\/web\//.test(lines[at(m.index) - 1])) bad.push([at(m.index), 'a value written into a quoted handler argument']);
  lines.forEach((l, i) => { if (/\bon[a-z]+="[^"]*'\$\{/.test(l) && !/^\s*\/\//.test(l)) bad.push([i + 1, 'a template value inside a handler’s quotes']); });
  if (bad.length) fail(`${bad.length} value(s) reach inline handler code without jsa(): `
    + bad.slice(0, 8).map(([n, w]) => `line ${n} (${w})`).join('; '));
  else pass('every value written into an inline handler goes through jsa()');
}

// ---- the keyboard reaches everything a click does (v1.92, item 36) ------------------------------
// WCAG 2.1.1, read off the markup, so it sees what the browser checks cannot: an open menu, a panel the
// run never opens, a message link. Every element carrying a click handler is a native control (button,
// input, select, textarea, option, summary, a link with an address). v1.92, revised before merge: the one
// non-native control allowed is an SVG <g> -- SVG has no button -- saying role="button" tabindex="0" and an
// aria-label BEFORE its handler (a delegate in the board makes Enter and Space work it). role="button" on a
// <td> broke the table, on an <a> with no address it was a link that was not one, and on a <span> or <div> it
// was a button without the browser's own keys: every one of those is now a <button>. Excepted: a
// backdrop that closes its box (every box has its own Close button) and a handler that only stops a click
// travelling on. Written as a rule because v1.91's browser check measured with every menu closed and so
// missed that no menu item could be reached from the keyboard at all.
{
  console.log('\nkeyboard reach (markup)');
  const at = i => src.slice(0, i).split('\n').length;
  const NATIVE = /^(button|input|select|textarea|option|summary)$/;
  const TAG = /^<([a-zA-Z][a-zA-Z0-9]*)\b/;
  const bad = [];
  for (const m of src.matchAll(/(?<![.\w])onclick\s*=\s*(\\?["'])/g)) {
    const i = m.index, ln = at(i), line = lines[ln - 1] || '';
    if (/^\s*(\/\/|\*|\/\*)/.test(line)) continue;
    // the value, as far as its own quote
    const q = m[1], v0 = i + m[0].length, v = src.slice(v0, v0 + 60);
    if (/^if\(event\.target===this\)/.test(v)) continue;                  // a backdrop
    if (/^event\.stopPropagation\(\)\s*$/.test(v.slice(0, v.indexOf(q.slice(-1)))) ) continue;
    // the tag it belongs to: the nearest '<' that opens an element
    let j = src.lastIndexOf('<', i), tag = null;
    while (j >= 0 && i - j < 1200) { const t = TAG.exec(src.slice(j, j + 24)); if (t) { tag = t[1].toLowerCase(); break; } j = src.lastIndexOf('<', j - 1); }
    if (!tag) { bad.push([ln, 'the element could not be read']); continue; }
    const head = src.slice(j, i);
    // A HANDLER HANDED TO A HELPER: the nearest tag closed before it ('>' not part of '=>'), so the text is an
    // argument -- act('onclick="…"', …) -- and the element is whatever the helper writes. Followed to it.
    if (/[^=]>/.test(head.slice(tag.length + 1))) {
      const h = /([A-Za-z_$][\w$]*)\(\s*\\?['"`]$/.exec(src.slice(Math.max(0, i - 48), i));
      const def = h && new RegExp('(?:const|let|var|function)\\s+' + h[1] + '\\b[^\\n]{0,120}?return\\s*\\\'<(\\w+)').exec(src);
      if (def && NATIVE.test(def[1].toLowerCase())) continue;
      bad.push([ln, `handed to ${h ? h[1] + '()' : 'a helper'}, which writes no control`]); continue;
    }
    if (NATIVE.test(tag)) continue;
    if (tag === 'a' && /\shref\s*=/.test(src.slice(j, i + 400).split(/>(?!=)/)[0] + src.slice(j, i))) continue;
    if (tag === 'g' && /role\s*=\s*\\?["']button\\?["']/.test(head) && /tabindex\s*=\s*\\?["']0\\?["']/.test(head)
        && /aria-label\s*=/.test(head)) continue;
    bad.push([ln, `<${tag}> ${v.replace(/\s+/g, ' ').slice(0, 34)}`]);
  }
  // AND NO role="button" ANYWHERE BUT AN SVG GROUP, handler or not.
  for (const m of src.matchAll(/role\s*=\s*\\?["']button\\?["']/g)) {
    const i = m.index, ln = at(i), line = lines[ln - 1] || '';
    if (/^\s*(\/\/|\*)/.test(line)) continue;                                   // a line comment
    if (src.lastIndexOf('/*', i) > src.lastIndexOf('*/', i)) continue;           // inside a block comment
    if (src[i - 1] === '[') continue;                                             // a CSS selector
    let j = src.lastIndexOf('<', i), tag = null;
    while (j >= 0 && i - j < 400) { const t = TAG.exec(src.slice(j, j + 24)); if (t) { tag = t[1].toLowerCase(); break; } j = src.lastIndexOf('<', j - 1); }
    if (tag !== 'g') bad.push([ln, `role="button" on <${tag || '?'}> — use a <button>`]);
  }
  if (bad.length) fail(`${bad.length} clickable element(s) not a native control — make each a <button> (an SVG <g> alone may `
    + `say role="button" tabindex="0" with an aria-label before its handler): ` + bad.slice(0, 12).map(([n, w]) => `line ${n} ${w}`).join('; ')
    + (bad.length > 12 ? ` … and ${bad.length - 12} more (KEYS_ALL=1 lists them all)` : '')
    + (process.env.KEYS_ALL ? '\n' + bad.map(([n, w]) => `        line ${n} ${w}`).join('\n') : ''));
  else pass('every element with a click handler is a native control or a labelled SVG role="button" group (backdrops excepted)');
}

// ---- every box is one the box controller can drive (v1.93, item 39) ----------------------------------------
// The controller (dlgSync) finds a box as a direct child of <body> with class modal-bg and an id, names it from
// its <h3>, and closes it -- on Esc, or after asking about typing -- by pressing the box's own close control. A
// box nested elsewhere, unnamed or without a close control would open with the keyboard left behind it, be read
// out as nothing, or have no way out but the mouse. The two boxes whose close control is drawn by their own code
// are listed in DLG_DRAWN_CLOSE.
console.log('\nboxes');
{
  const { JSDOM } = await import('jsdom');
  const doc = new JSDOM(src.replace(/<script[\s\S]*?<\/script>/gi, '')).window.document;
  const drawn = literal('DLG_DRAWN_CLOSE');
  const bad = [], ids = new Set();
  const all = [...doc.querySelectorAll('.modal-bg')];
  for (const bg of all) {
    const id = bg.id || '(no id)';
    if (!bg.id) { bad.push('a box with no id'); continue; }
    if (ids.has(bg.id)) bad.push(`${id}: the id is used twice`); ids.add(bg.id);
    if (bg.parentElement !== doc.body) bad.push(`${id}: not a direct child of <body>`);
    const m = bg.querySelector(':scope > .modal');
    if (!m) { bad.push(`${id}: no .modal inside`); continue; }
    const h = m.querySelector('h3');
    const name = h ? [...h.childNodes].filter(n => !(n.nodeType === 1 && n.tagName === 'BUTTON')).map(n => n.textContent).join('').trim() : '';
    if (!name && !drawn.includes(bg.id)) bad.push(`${id}: no <h3> naming it`);
    const close = m.querySelector('h3 button.x') || [...m.querySelectorAll('button')].find(x => /^(✕\s*)?(Close|Cancel)$/.test(x.textContent.trim()));
    if (!close && !drawn.includes(bg.id)) bad.push(`${id}: no close control (✕ Close in the <h3>)`);
  }
  for (const id of drawn) if (!ids.has(id)) bad.push(`DLG_DRAWN_CLOSE names ${id}, which is not a box`);
  if (bad.length) fail(`${bad.length} box(es) the controller cannot drive: ` + bad.join('; '));
  else pass(`all ${all.length} boxes are direct children of <body> with an id, a .modal, a name and a close control`);
}

// ---- every award sort uses the one order (v1.94, item 46; v1.95, item 56) -------------------------------
// Awards are taken by date, and awards on one date in the order they arrived on it: discretionary fills them
// forward and mandatory backward in that order, so it is money. awdCmp() is that order -- equal dates compare
// EQUAL, and the stable sort keeps their stored order. The comparators it replaced returned 1 for equal dates,
// which the language leaves undefined; Chromium happened to keep the order and another browser need not, and no
// suite can tell, because in Chromium the result is the same. So it is checked here.
//
// v1.95 (item 56): an outside review got three unsafe sorts past the v1.94 rule. It read a sort's receiver back
// only to the previous ; { or }, so `(aw.inc||[]).filter(function(e){ return e.d; }).sort(<unsafe>)` was read as
// `).sort(` and never seen as awards; it let through anything that mentioned awdCmp, `awdCmp(a,b)||1` among them,
// which breaks every tie; and it could not see an unsafe comparator held in a name. Now:
//   - the script is read as code: the text of strings, template literals, regular expressions and comments is set
//     aside first, so a bracket or a name inside one is never taken for code -- and the brackets must balance
//     after, or the rule says it could not read the script rather than pass it;
//   - a sort's receiver is the WHOLE chained expression, walked back over balanced brackets to where it starts;
//   - a sort is of awards when that receiver names inc, or its comparator -- written in place, or what a name given
//     to it is defined as -- reads an award's date (awdKey, awdDay, awdCmp, or a .d or .day);
//   - a sort of awards takes awdCmp itself, or a comparator that returns exactly `awdCmp(a…, b…) || <tie-break>`, the
//     tie-break comparing a value of its first argument with one of its second (a subtraction, a localeCompare or a
//     three-way ?: compare), never a constant. Any other comparator is refused, a name for one included.
// The rule has its own test (awardOrderSelftest, below; `node tools/check.mjs --selftest` runs it alone): the
// review's three bypasses and the other unsafe forms must be refused, the valid forms passed. It runs before the
// rule judges the board: a rule that cannot fail proves nothing.
console.log('\naward order');
{
  const st = awardOrderSelftest();
  if (st.bad.length) fail(`the award-order rule fails its own test: ${st.bad.join('; ')}`);
  else pass(`the award-order rule's own test: ${st.refused} unsafe forms refused (the review's three bypasses among them), ${st.passed} valid forms passed`);
  const bad = [], at = i => src.slice(0, i).split('\n').length;
  let sorts = 0, awards = 0;
  for (const m of src.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi)) {
    if (/type\s*=\s*["']?application\/json/i.test(m[1])) continue;
    const base = m.index + m[0].indexOf('>') + 1, r = awardSortFindings(m[2]);
    if (r.unreadable) { bad.push(`the script at line ${at(base)} could not be read: ${r.unreadable}`); continue; }
    sorts += r.sorts; awards += r.awards;
    r.findings.forEach(f => bad.push(`line ${at(base + f.at)}: ${f.text} -- ${f.why}`));
  }
  if (bad.length) fail(`${bad.length} award sort(s) not using awdCmp — equal dates must compare equal: ` + bad.join('; '));
  else pass(`every sort of awards uses awdCmp (${awards} of ${sorts} sorts are of awards)`);
}

// The award-order rule, on one script's text. Returns {sorts, awards, findings:[{at, text, why}], unreadable}.
function awardSortFindings(js) {
  const B = jsBlank(js);
  const CLOSE = { '(': ')', '[': ']', '{': '}' }, OPEN = { ')': '(', ']': '[', '}': '{' };
  {   // read as code, the brackets balance -- or the rule cannot trust anything it reads here
    const stk = [];
    for (let k = 0; k < B.length; k++) {
      const c = B[k];
      if (c in CLOSE) stk.push(c);
      else if (c in OPEN && stk.pop() !== OPEN[c]) return { sorts: 0, awards: 0, findings: [], unreadable: `an unmatched ${c} at offset ${k}` };
    }
    if (stk.length) return { sorts: 0, awards: 0, findings: [], unreadable: `${stk.length} bracket(s) never closed` };
  }
  const fwd = (s, k) => { const stk = []; for (let j = k; j < s.length; j++) { const c = s[j];
    if (c in CLOSE) stk.push(CLOSE[c]); else if (c in OPEN) { if (stk.pop() !== c) return -1; if (!stk.length) return j; } } return -1; };
  const back = (s, k) => { const stk = []; for (let j = k; j >= 0; j--) { const c = s[j];
    if (c in OPEN) stk.push(OPEN[c]); else if (c in CLOSE) { if (stk.pop() !== c) return -1; if (!stk.length) return j; } } return -1; };
  const ws = j => { while (j > 0 && /\s/.test(B[j - 1])) j--; return j; };
  const word = k => { let s = k; while (s > 0 && /[\w$]/.test(B[s - 1])) s--; return s; };
  const STOP = /^(return|typeof|instanceof|in|of|new|delete|void|throw|case|do|else|yield|await|if|while|for|switch|catch|with)$/;
  // where the chained expression that ends at i (the '.' of '.sort(') starts
  const start = i => {
    let j = i;
    for (;;) {
      const k = ws(j), c = B[k - 1] || '';
      if (c === ')' || c === ']') {                       // a call, an index, a group or an array
        const o = back(B, k - 1); if (o < 0) return -1;
        j = o; const p = ws(j), pc = B[p - 1] || '';
        if (/[\w$]/.test(pc)) { if (STOP.test(B.slice(word(p), p))) return j; j = p; continue; }
        if (pc === ')' || pc === ']') { j = p; continue; }
        if (pc === '.' && B[p - 2] === '?') { j = p - 2; continue; }
        return j;
      }
      if (/[\w$]/.test(c)) { const s = word(k); if (STOP.test(B.slice(s, k))) return j; j = s; }
      else if (c === "'" || c === '"' || c === '`') { const s = B.lastIndexOf(c, k - 2); return s; }
      else return j;
      const p = ws(j);
      if (B[p - 1] === '.' && B[p - 2] !== '.') { j = B[p - 2] === '?' ? p - 2 : p - 1; continue; }
      return j;
    }
  };
  const reads = t => /\bawd(?:Key|Day|Cmp)\b/.test(t) || /[\w$\])]\s*\.\s*(?:d|day)\b(?!\s*[\w$.(\[])/.test(t);
  // what a name is defined as in this script: each `function name(…){…}`, and each `const|let|var name = …`
  const defs = name => {
    const out = [], n = name.replace(/\$/g, '\\$');
    for (const m of B.matchAll(new RegExp(`\\bfunction\\s+${n}\\s*\\(`, 'g'))) {
      const pc = fwd(B, m.index + m[0].length - 1), ob = pc < 0 ? -1 : B.indexOf('{', pc), cb = ob < 0 ? -1 : fwd(B, ob);
      if (cb > 0) out.push(B.slice(m.index, cb + 1));
    }
    for (const m of B.matchAll(new RegExp(`\\b(?:const|let|var)\\s+${n}\\s*=(?!=)`, 'g'))) {
      let k = m.index + m[0].length, d = 0;
      for (; k < B.length && k - m.index < 4000; k++) { const c = B[k];
        if (c in CLOSE) d++; else if (c in OPEN) { if (!d) break; d--; } else if (!d && (c === ';' || c === ',')) break; }
      out.push(B.slice(m.index + m[0].length, k).trim());
    }
    return out;
  };
  const findings = [];
  let sorts = 0, awards = 0;
  for (const m of B.matchAll(/\.\s*(?:sort|toSorted)\s*\(/g)) {
    sorts++;
    const i = B[m.index - 1] === '?' ? m.index - 1 : m.index, op = m.index + m[0].length - 1, cp = fwd(B, op);
    const s = start(i);
    const text = (js.slice(i, op + 1) + js.slice(op + 1, cp < 0 ? op + 60 : cp).trim().replace(/\s+/g, ' ').slice(0, 60) + ')');
    if (s < 0 || cp < 0) { findings.push({ at: i, text, why: 'the sort could not be read as code' }); continue; }
    const recv = B.slice(s, i), arg = B.slice(op + 1, cp).trim(), named = /^[\w$]+$/.test(arg);
    const def = named && arg !== 'awdCmp' ? defs(arg) : [];
    if (!(/\binc\b/.test(recv) || reads(arg) || def.some(reads))) continue;
    awards++;
    const why = cmpVerdict(arg, def);
    if (why) findings.push({ at: i, text, why });
  }
  return { sorts, awards, findings, unreadable: null };

  // null when the comparator is awdCmp's order, or why it is not
  function cmpVerdict(arg, def) {
    if (arg === 'awdCmp') return null;
    if (!arg) return 'no comparator: a sort of awards takes awdCmp';
    if (/^[\w$]+$/.test(arg)) return `${arg} is not a known award comparator${def.length ? '' : ' (nothing here defines it)'}: sort awards with awdCmp, or with awdCmp(…) || a tie-break written in place`;
    const f = /^function\s*[\w$]*\s*\(\s*([\w$]+)\s*,\s*([\w$]+)\s*\)\s*\{([\s\S]*)\}$/.exec(arg)
           || /^\(\s*([\w$]+)\s*,\s*([\w$]+)\s*\)\s*=>\s*([\s\S]*)$/.exec(arg);
    if (!f) return 'a comparator that is not awdCmp';
    const [, a, b] = f; let body = f[3].trim();
    if (arg.startsWith('function') || body.startsWith('{')) {
      if (!arg.startsWith('function')) { if (!body.endsWith('}')) return 'a comparator that cannot be read'; body = body.slice(1, -1).trim(); }
      const r = /^return\b([\s\S]*?);?$/.exec(body);
      if (!r || split(r[1], ';').length > 1) return 'a comparator that does more than return awdCmp(…) || a tie-break';
      body = r[1].trim();
    }
    const parts = split(body, '||');
    const of = (x, p) => new RegExp(`^${p.replace(/\$/g, '\\$')}(?:\\s*\\.\\s*[\\w$]+)*$`).test(unwrap(x));
    parts[0] = unwrap(parts[0]);
    const call = /^awdCmp\s*\(/.exec(parts[0]);
    const args = call && fwd(parts[0], call[0].length - 1) === parts[0].length - 1 ? split(parts[0].slice(call[0].length, -1), ',') : null;
    if (!args) return 'a comparator that does not decide by awdCmp';
    if (args.length !== 2 || !of(args[0], a) || !of(args[1], b)) return `awdCmp must be given the first argument's award, then the second's (${a}…, ${b}…)`;
    if (parts.length < 2) return 'awdCmp(…) with nothing after it: sort with awdCmp itself, or add || a tie-break';
    for (const t of parts.slice(1)) {
      const u = unwrap(t), one = (x, y) => (of(x, a) && of(y, b)) || (of(x, b) && of(y, a));
      if (/^[-+]?\s*(\d|\.\d)|^(true|false|null|undefined|NaN|Infinity)$/.test(u)) return `a constant (${u}) decides ties: equal dates must compare equal, or be told apart by a value of each`;
      const sub = split(u, '-'), lc = /^([\s\S]+)\.localeCompare\(([\s\S]+)\)$/.exec(u);
      const tw = /^([\s\S]+?)\s*<\s*([\s\S]+?)\s*\?\s*-\s*1\s*:\s*\(?\s*([\s\S]+?)\s*>\s*([\s\S]+?)\s*\?\s*1\s*:\s*0\s*\)?$/.exec(u);
      if (sub.length === 2 && one(sub[0], sub[1])) continue;
      if (lc && one(lc[1], lc[2])) continue;
      if (tw && one(tw[1], tw[2]) && unwrap(tw[3]) === unwrap(tw[1]) && unwrap(tw[4]) === unwrap(tw[2])) continue;
      return `the tie-break (${u.replace(/\s+/g, ' ').slice(0, 40)}) does not compare a value of ${a} with one of ${b}`;
    }
    return null;
  }
  // s split at each sep outside brackets
  function split(s, sep) {
    const out = []; let d = 0, last = 0;
    for (let k = 0; k < s.length; k++) {
      const c = s[k];
      if (c in CLOSE) d++; else if (c in OPEN) d--;
      else if (!d && s.startsWith(sep, k)) { out.push(s.slice(last, k)); k += sep.length - 1; last = k + 1; }
    }
    out.push(s.slice(last)); return out.map(x => x.trim());
  }
  function unwrap(s) { s = s.trim(); while (s[0] === '(' && fwd(s, 0) === s.length - 1) s = s.slice(1, -1).trim(); return s; }
}

// The script with what is not code set aside: the text of every string, template literal, regular expression and
// comment becomes spaces (newlines kept, so every position and line is where it was). A / is a regular expression
// where an expression can start (after an operator, an opening bracket, a keyword such as return, or a }), and a
// division after a name, a number or a closing bracket.
function jsBlank(js) {
  const o = js.split(''), n = js.length;
  const KW = new Set(['return', 'typeof', 'instanceof', 'in', 'of', 'new', 'delete', 'void', 'throw', 'case', 'do', 'else', 'yield', 'await']);
  const blank = (a, b) => { for (let k = a; k < b; k++) if (o[k] !== '\n') o[k] = ' '; };
  const tpl = [];
  let depth = 0, prev = '', i = 0;
  // a template literal's text from k: blank to its closing ` or to its next ${, which is code
  const text = k => {
    const s = k;
    while (k < n) {
      if (js[k] === '\\') { k += 2; continue; }
      if (js[k] === '`') { blank(s, k); prev = 'v'; return k + 1; }
      if (js[k] === '$' && js[k + 1] === '{') { blank(s, k); tpl.push(depth); prev = '{'; return k + 2; }
      k++;
    }
    blank(s, n); return n;
  };
  while (i < n) {
    const c = js[i], d = js[i + 1];
    if (c === '/' && d === '/') { let e = js.indexOf('\n', i); if (e < 0) e = n; blank(i, e); i = e; continue; }
    if (c === '/' && d === '*') { let e = js.indexOf('*/', i + 2); e = e < 0 ? n : e + 2; blank(i, e); i = e; continue; }
    if (c === "'" || c === '"') {
      let k = i + 1; while (k < n && js[k] !== c && js[k] !== '\n') k += js[k] === '\\' ? 2 : 1;
      blank(i + 1, k); i = k + 1; prev = 'v'; continue;
    }
    if (c === '`') { i = text(i + 1); continue; }
    if (c === '/' && (prev === '' || prev === 'kw' || '(,=:[!&|?{};+-*%<>~^}'.includes(prev))) {
      let k = i + 1, cls = false;
      while (k < n && js[k] !== '\n' && (js[k] !== '/' || cls)) { if (js[k] === '\\') k++; else if (js[k] === '[') cls = true; else if (js[k] === ']') cls = false; k++; }
      if (js[k] === '/') { blank(i + 1, k); i = k + 1; while (/[a-z]/.test(js[i] || '')) i++; prev = 'v'; continue; }
    }
    if (/[\w$]/.test(c)) { let k = i; while (k < n && /[\w$]/.test(js[k])) k++; prev = KW.has(js.slice(i, k)) ? 'kw' : 'v'; i = k; continue; }
    if (c === '{') depth++;
    else if (c === '}') { if (tpl.length && tpl[tpl.length - 1] === depth) { tpl.pop(); i = text(i + 1); continue; } depth--; }
    if (!/\s/.test(c)) prev = c;
    i++;
  }
  return o.join('');
}

// THE RULE'S OWN TEST (v1.95, item 56). Each case is a small script with one sort in it. The first three are the ones
// the outside review got past v1.94's rule (v195r/me/r10.txt); every unsafe case must be refused -- for the reason given,
// where one is -- and every valid one passed.
function awardOrderSelftest() {
  const UNSAFE = [
    ['review bypass 1: an unsafe sort after a .filter(function(){…})',
      "function __p1(aw){ return (aw.inc||[]).filter(function(e){ return e.d; }).sort(function(a,b){ return a.d<b.d?-1:1; }); }", /not decide by awdCmp/],
    ['review bypass 2: awdCmp(a,b)||1',
      "function __p2(aw){ return aw.inc.sort((a,b)=>awdCmp(a,b)||1); }", /a constant \(1\)/],
    ['review bypass 3: an unsafe comparator held in a name',
      "function __p5(list){ const byDate=(a,b)=>a.d<b.d?-1:1; return list.sort(byDate); }", /byDate is not a known award comparator:/],
    ["v1.93's own: the comparator on the line below its receiver",
      "function f(id){\n  S.awards[id].inc\n    .sort((a,b)=>a.d<b.d?-1:1);\n}"],
    ["v1.93's own: keys compared by hand",
      "function f(aw){ return aw.inc.map(function(x, j){ return {x:x, j:j}; })\n  .sort(function(a, b){ const ka=awdKey(a.x), kb=awdKey(b.x); return ka<kb?-1:1; }); }"],
    ['a constant after awdCmp: ||-1', "function f(aw){ aw.inc.sort(function(a,b){ return awdCmp(a,b)||-1; }); }", /a constant \(-1\)/],
    ['a constant after awdCmp: ||(0)', "function f(aw){ aw.inc.sort((a,b)=>{ return awdCmp(a,b)||(0); }); }", /a constant \(0\)/],
    ['a tie-break comparing a value with itself', "function f(o){ return o.inc.sort(function(a,b){ return awdCmp(a.x,b.x)||(a.j-a.j); }); }"],
    ['awdCmp given the awards the wrong way round', "function f(aw){ aw.inc.sort((a,b)=>awdCmp(b,a)||(a.j-b.j)); }"],
    ['awdCmp wrapped with no tie-break', "function f(o){ return o.inc.map(x=>({x})).sort((a,b)=>awdCmp(a.x,b.x)); }"],
    ['a second statement before the return', "function f(aw){ aw.inc.sort(function(a,b){ log(a); return awdCmp(a,b)||(a.j-b.j); }); }"],
    ['a name for a comparator, on awards', "function f(aw, byWhen){ return aw.inc.slice().sort(byWhen); }"],
    ['a name defined as a function declaration that compares dates',
      "function byWhen(x, y){ return x.d<y.d?-1:1; }\nfunction f(list){ return list.sort(byWhen); }"],
    ['no comparator at all', "function f(aw){ return aw.inc.slice().sort(); }"],
    ['toSorted', "function f(aw){ return aw.inc.toSorted((a,b)=>a.d<b.d?-1:1); }"],
    ['a sort comparing dates, whatever its list is called', "function f(list){ return list.sort((p,q)=>p.d<q.d?-1:(p.d>q.d?1:0)); }"],
    // the receiver alone says these are awards (the comparators read no date), so each proves the walk back to it
    ['awards sorted by something else, after a .filter(function(){…})',
      "function f(aw){ return (aw.inc||[]).filter(function(e){ return e.d; }).sort(function(a,b){ return a.j<b.j?-1:1; }); }"],
    ['a string holding brackets inside the chain',
      "function f(aw){ return (aw.inc||[]).filter(function(e){ return e.n!==')}('; }).sort((a,b)=>a.n<b.n?-1:1); }"],
    ['a regular expression holding brackets inside the chain',
      "function f(aw){ return (aw.inc||[]).filter(function(e){ return !/[)}(]/.test(e.n); }).sort((a,b)=>a.n<b.n?-1:1); }"],
    ['a template literal and comments inside the chain, over three lines',
      "function f(aw){ return (aw.inc||[]).filter(function(e){ /* } ) */ return `${e.n}}` !== '}'; }) // )\n  .map(function(e){ return {n:e.n}; })\n  .sort((a,b)=>a.n<b.n?-1:1); }"],
    ['an index and a call before it', "function f(id){ return S.awards[id].inc.slice(0).reverse().sort(function(a,b){ return 1; }); }"],
  ];
  const VALID = [
    ['.sort(awdCmp)', "function f(aw){ aw.inc.sort(awdCmp); }"],
    ['.slice().sort(awdCmp)', "function f(aw){ return aw.inc.slice().sort(awdCmp); }"],
    ['after a .filter(function(){…}), .slice().sort(awdCmp)', "function f(aw){ return (aw.inc||[]).filter(function(x){ return x && x.d; }).slice().sort(awdCmp)[0]; }"],
    ['.sort(function(a,b){ return awdCmp(a.x,b.x)||(a.j-b.j); })',
      "function f(aw){ return aw.inc.map(function(x, j){ return {x:x, j:j}; })\n  .sort(function(a,b){ return awdCmp(a.x,b.x)||(a.j-b.j); }); }"],
    ['an arrow, a localeCompare tie-break', "function f(o){ return o.inc.sort((p,q)=>awdCmp(p.x,q.x) || p.id.localeCompare(q.id)); }"],
    ['a three-way tie-break', "function f(o){ return o.inc.sort((p,q)=>{ return awdCmp(p.x,q.x) || (p.k<q.k? -1 : (p.k>q.k? 1 : 0)); }); }"],
    ['a sort that is not of awards, with a named comparator', "function g(rest, cmp){ return rest.slice().sort(cmp); }"],
    ['a sort that is not of awards', "function g(list){ list.sort(function(a,b){ return (a.rank||9e9)-(b.rank||9e9) || a.i-b.i; }); }"],
    ['a .d that is not a date', "function g(ids, Y){ return ids.map(id=>Y.rows[id]).sort((p,q)=>Math.abs(q.d.fund)-Math.abs(p.d.fund)); }"],
    ['inc in a string is not awards', "function g(){ return ['inc', 'dec'].sort(); }"],
    ['inc earlier in the statement, not in the receiver', "function g(aw, list){ return aw.inc.length && list.slice().sort((p,q)=>p.n-q.n); }"],
    ['inc in the statement before', "function g(aw, list){ const n=aw.inc.length; list.sort(function(a,b){ return a.n-b.n; }); return n; }"],
  ];
  const bad = [];
  for (const [what, js, why] of UNSAFE) {
    const r = awardSortFindings(js);
    if (r.unreadable || !r.findings.length) bad.push(`not refused: ${what}${r.unreadable ? ' (could not be read: ' + r.unreadable + ')' : ''}`);
    else if (why && !why.test(r.findings[0].why)) bad.push(`refused for the wrong reason: ${what} (${r.findings[0].why})`);
  }
  for (const [what, js] of VALID) { const r = awardSortFindings(js); if (r.unreadable || r.findings.length) bad.push(`refused: ${what} (${r.unreadable || r.findings[0].why})`); }
  return { bad, refused: UNSAFE.length, passed: VALID.length };
}

// ---- the PowerPoint template is data, and only data (v2.00) ------------------------------------
// TPL_PARTS is the one place a reviewer cannot read: 1.6 MB of base64 on a single line. The fence
// comment around it (§36) promises it holds no code; this proves it. The line is parsed as JSON,
// every value must be base64, and its SHA-256 must match the fingerprint recorded beside this file.
// A change to the template is deliberate and re-records the hash; an accidental edit fails here.
console.log('\npowerpoint template');
try {
  const line = lines.find(l => l.startsWith('const TPL_PARTS='));
  if (!line) fail('could not find the TPL_PARTS line');
  else if (lines.filter(l => l.startsWith('const TPL_PARTS=')).length !== 1) fail('TPL_PARTS is declared more than once');
  else if (!line.endsWith('};')) fail('the TPL_PARTS line does not end its object — it may have been reflowed');
  else {
    let obj;
    try { obj = JSON.parse(line.slice('const TPL_PARTS='.length, -1)); }
    catch (e) { obj = null; fail(`TPL_PARTS is not a JSON object on one line: ${e.message}`); }
    if (obj) {
      const notB64 = Object.keys(obj).filter(k => typeof obj[k] !== 'string' || !/^[A-Za-z0-9+/]*={0,2}$/.test(obj[k]));
      if (notB64.length) fail(`TPL_PARTS holds a value that is not base64: ${notB64.slice(0, 3).join(', ')}`);
      else pass(`TPL_PARTS parses as ${Object.keys(obj).length} base64 parts and holds no code`);
      const { createHash } = await import('node:crypto');
      const want = readFileSync(new URL('./tpl-parts.sha256', import.meta.url), 'utf8').trim();
      const got = createHash('sha256').update(line, 'utf8').digest('hex');
      if (got !== want) fail(`the template line's SHA-256 ${got.slice(0, 12)}… does not match tools/tpl-parts.sha256 ${want.slice(0, 12)}… — if the change was intended, re-record it`);
      else pass('the template line matches its recorded fingerprint');
    }
  }
} catch (e) {
  fail(e.message);
}

// ---- the mutation list parses (v2.01) ------------------------------------------------------------
// mutate.mjs is read as TEXT during development (mcount.py, mkmut.py), and a text reader forgives what a JavaScript
// parser does not: v2.00 merged with two entries missing a comma, so `npm run mutate` and validate:math died loading it,
// and nothing said so until v2.01's sweep. `node --check` parses the file and runs none of it -- the rule holds.
console.log('\nmutation list');
try {
  execFileSync(process.execPath, ['--check', new URL('./export-audit/mutate.mjs', import.meta.url).pathname], { stdio: 'pipe' });
  pass('tools/export-audit/mutate.mjs parses (node --check: read, never run)');
} catch (e) {
  fail('tools/export-audit/mutate.mjs does not parse: ' + String((e.stderr || e.message)).split('\n').filter(Boolean).slice(0, 3).join(' | '));
}

// ---- a requirement's fields are named in one place (v2.03, item 20) --------------------------------------
// REQ_FIELD names every field; the RECORD panel, the pop-ups, the submittal review, the proposal gate, the messages and
// the guide read it. A test went hollow in v1.86 when one name changed in one place and not another, so this holds the
// three ways a label used to be spelled by hand: recF() given a label rather than a key; PMO_FIELDS spelling a label;
// and the three written fields' names -- Impact statement, Description & note, Requirement edit -- written anywhere in
// the program or the guide but the registry (comments aside: they are history, and are not shown).
console.log('\nfield labels');
try {
  const at = src.indexOf('\nconst REQ_FIELD={');
  const end = at < 0 ? -1 : src.indexOf('\n};', at);
  if (at < 0 || end < 0) fail('could not find REQ_FIELD');
  else {
    const RF = new Function('return (' + src.slice(at + '\nconst REQ_FIELD='.length, end + 2) + ')')();
    const keys = new Set(Object.keys(RF));
    const lits = [...src.matchAll(/\brecF\('([^']*)'\s*,/g)].map(m => m[1]);
    const notKey = lits.filter(k => !keys.has(k));
    if (!lits.length) fail('found no recF() call to check');
    else if (notKey.length) fail(`recF() is given a label, not a REQ_FIELD key: ${notKey.map(k => JSON.stringify(k)).join(', ')}`);
    else pass(`all ${lits.length} recF() fields are named by a REQ_FIELD key`);
    const pa = src.indexOf('\nconst PMO_FIELDS = ['), pb = pa < 0 ? -1 : src.indexOf('\n];', pa);
    const rows = pa < 0 ? [] : src.slice(pa, pb).split('\n').filter(l => /^\s*\['/.test(l));
    const badRows = rows.filter(l => { const m = l.match(/^\s*\['(\w+)',\s*FL\('(\w+)'\)\],?\s*$/); return !m || m[1] !== m[2] || !keys.has(m[1]); });
    if (!rows.length) fail('found no PMO_FIELDS entry to check');
    else if (badRows.length) fail(`PMO_FIELDS spells a label instead of FL(<its key>): ${badRows.map(l => l.trim()).slice(0, 3).join(' | ')}`);
    else pass(`all ${rows.length} PMO_FIELDS entries read their label from REQ_FIELD`);
    const own = ['cons', 'dn', 'rec'].map(k => RF[k] && RF[k].l).filter(Boolean);
    const forms = [...new Set(own.flatMap(l => [l, l.replace(/&/g, '&amp;')]))];
    const regStart = src.slice(0, at).split('\n').length + 1, regEnd = src.slice(0, end).split('\n').length + 1;
    const hits = [];
    lines.forEach((l, i) => {
      const n = i + 1;
      if (n >= regStart && n <= regEnd) return;                    // the registry itself
      if (/^\s*(\/\/|\/\*|\*)/.test(l)) return;                     // a comment line
      const code = l.replace(/\s\/\/\s.*$/, '');                     // and a trailing comment
      forms.forEach(f => { if (code.includes(f)) hits.push(n + ': ' + f); });
    });
    if (own.length !== 3) fail('REQ_FIELD lost one of cons, dn, rec');
    else if (hits.length) fail(`a written field's name is spelled outside REQ_FIELD (${hits.length}): ${hits.slice(0, 4).join('; ')}`);
    else pass('Impact statement, Description & note and Requirement edit are spelled only in REQ_FIELD (the guide reads them by data-fl)');
  }
} catch (e) {
  fail('field labels: ' + e.message);
}

// ---- build stamp -------------------------------------------------------------------------------
const build = src.match(/^const BUILD\s*=\s*'([^']+)'/m)?.[1];
console.log(`\nBUILD  ${build || 'NOT FOUND'}`);

// .gitignore is an allowlist (*.html, *.json with named exceptions), so a file added to this repo
// is ignored unless someone remembers to except it — and a commit can then silently omit the very
// thing it says it adds. That has happened once. Check it rather than trust it.
console.log('\ntracked by git');
for (const f of ['prioritization-board-grid.html', 'tools/row-controls.json']) {
  try {
    execFileSync('git', ['check-ignore', '-q', f], { cwd: new URL('..', import.meta.url).pathname });
    fail(`${f} is git-ignored — it will not be committed`);
  } catch (e) {
    if (e.status === 1) pass(`${f}`);            // exit 1 from check-ignore means NOT ignored
    else fail(`${f} — could not ask git (${e.message.split('\n')[0]})`);
  }
}
if (!build) failed++;

console.log(failed ? `\n${failed} check(s) failed\n` : '\nall checks passed\n');
process.exit(failed ? 1 : 0);
